def solve(weights, values, capacity):
    # 0/1 knapsack using DP over capacity.
    # Guard against invalid capacity.
    if capacity <= 0:
        return 0
    # Ensure capacity is integer
    capacity = int(capacity)
    dp = [0] * (capacity + 1)
    for w, v in zip(weights, values):
        # Skip items with non-positive weight (weight 0 allowed) or negative value.
        if w < 0 or v < 0:
            continue
        # Convert weight to int
        w = int(w)
        if w > capacity:
            # cannot fit, skip
            continue
        for c in range(capacity, w - 1, -1):
            new_val = dp[c - w] + v
            if new_val > dp[c]:
                dp[c] = new_val
    return dp[capacity]

