    pq = [(0, 0)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    return dist[n - 1] if dist[n - 1] != float('inf') else -1

def solve(n: int, b: int) -> str:
    """Convert integer n to a string representation in base b (2 <= b <= 36).
    Uses digits 0-9 and a-z for values 10-35. Negative numbers get a leading '-'.
    """
    if b < 2 or b > 36:
        raise ValueError('Base must be between 2 and 36')
    if n == 0:
        return '0'
    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    sign = ''
    if n < 0:
        sign = '-'
        n = -n
    res_chars = []
    while n > 0:
        n, rem = divmod(n, b)
        res_chars.append(digits[rem])
    return sign + ''.join(reversed(res_chars))

