def solve(coins, amount):
    # Unbounded coin change: minimum number of coins to make amount
    # Return -1 if impossible.
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Filter out non-positive coin values
    coins = [c for c in coins if c > 0]
    if not coins:
        return -1
    max_val = amount + 1  # sentinel larger than any possible answer
    dp = [max_val] * (amount + 1)
